import {
  PersonalApiKeySchema,
  type PersonalApiKey,
} from "@aventurevc/api-schemas/personal/api-key";

import { cliApiTarget } from "./api-target";
import { credentialSafeMessage } from "./credential-redaction";

export type PersonalCredentialActivation = "pending" | "active";

/** CLI-owned keyring value composed from canonical server metadata and the opaque key secret. */
export interface PersonalCredential {
  readonly apiKey: PersonalApiKey;
  readonly secret: string;
}

export interface StoredPersonalCredential {
  readonly host: string;
  readonly activation: PersonalCredentialActivation;
  readonly credential: PersonalCredential;
}

export type PersonalCredentialLookup =
  | { readonly state: "found"; readonly stored: StoredPersonalCredential }
  | { readonly state: "missing" }
  | { readonly state: "unavailable"; readonly summary: string };

const KEYRING_SERVICE = "vc.aventure.aventure-cli";
const SERIALIZATION_PREFIX = "aventure-cli-personal-v1";

export async function savePersonalCredential(
  host: string,
  credential: PersonalCredential,
  activation: PersonalCredentialActivation,
): Promise<StoredPersonalCredential> {
  const canonicalHost = canonicalPersonalCredentialHost(host);
  const serialized = serializeCredential(credential, activation);
  const entry = await keyringEntry(canonicalHost);
  let writeFailure: unknown;
  try {
    await entry.setPassword(serialized);
  } catch (error) {
    writeFailure = error;
  }
  let observed: string | undefined;
  try {
    observed = (await entry.getPassword()) ?? undefined;
  } catch (error) {
    throw new Error(
      `OS credential storage write outcome is unknown (${errorSummary(writeFailure ?? error, [serialized, credential.secret])}); broker acknowledgement was withheld. Re-run auth status before retrying.`,
      { cause: error },
    );
  }
  if (observed !== serialized) {
    throw new Error(
      `OS credential storage did not confirm a durable write (${errorSummary(writeFailure, [serialized, credential.secret])}); broker acknowledgement was withheld.`,
      writeFailure === undefined ? undefined : { cause: writeFailure },
    );
  }
  return { host: canonicalHost, activation, credential };
}

export async function loadPersonalCredential(host: string): Promise<PersonalCredentialLookup> {
  const canonicalHost = canonicalPersonalCredentialHost(host);
  let serialized: string | undefined;
  try {
    const entry = await keyringEntry(canonicalHost);
    serialized = (await entry.getPassword()) ?? undefined;
  } catch (error) {
    return {
      state: "unavailable",
      summary: `OS credential storage is unavailable (${errorSummary(error)})`,
    };
  }
  if (serialized === undefined) return { state: "missing" };
  return {
    state: "found",
    stored: { host: canonicalHost, ...parseCredential(serialized) },
  };
}

export async function forgetPersonalCredential(host: string): Promise<void> {
  const canonicalHost = canonicalPersonalCredentialHost(host);
  const entry = await keyringEntry(canonicalHost);
  let deleteFailure: unknown;
  try {
    await entry.deleteCredential();
  } catch (error) {
    deleteFailure = error;
  }
  try {
    const observed = (await entry.getPassword()) ?? undefined;
    if (observed === undefined) return;
  } catch (error) {
    throw new Error(
      `OS credential removal outcome is unknown (${errorSummary(deleteFailure ?? error)})`,
      { cause: error },
    );
  }
  throw new Error(
    `OS credential storage did not confirm removal (${errorSummary(deleteFailure)})`,
    {
      cause: deleteFailure,
    },
  );
}

export function canonicalPersonalCredentialHost(host: string): string {
  return cliApiTarget(host).host;
}

async function keyringEntry(host: string) {
  const { AsyncEntry } = await import("@napi-rs/keyring");
  return new AsyncEntry(KEYRING_SERVICE, host);
}

function serializeCredential(
  credential: PersonalCredential,
  activation: PersonalCredentialActivation,
): string {
  return `${SERIALIZATION_PREFIX}:${activation}\n${JSON.stringify(credential.apiKey)}\n${credential.secret}`;
}

function parseCredential(serialized: string): {
  readonly activation: PersonalCredentialActivation;
  readonly credential: PersonalCredential;
} {
  const metadataStart = serialized.indexOf("\n");
  const secretStart = metadataStart < 0 ? -1 : serialized.indexOf("\n", metadataStart + 1);
  const header = metadataStart < 0 ? serialized : serialized.slice(0, metadataStart);
  const activation = header === `${SERIALIZATION_PREFIX}:active` ? "active" : "pending";
  if (
    metadataStart < 0 ||
    secretStart < 0 ||
    (header !== `${SERIALIZATION_PREFIX}:pending` && header !== `${SERIALIZATION_PREFIX}:active`)
  ) {
    throw new Error("OS credential entry has an unsupported format");
  }
  const secret = serialized.slice(secretStart + 1);
  if (secret.length === 0) {
    throw new Error("OS credential entry has an empty secret");
  }
  let metadata: unknown;
  try {
    metadata = JSON.parse(serialized.slice(metadataStart + 1, secretStart));
  } catch (error) {
    throw new Error("OS credential entry failed canonical schema validation", { cause: error });
  }
  const parsed = PersonalApiKeySchema.safeParse(metadata);
  if (!parsed.success) {
    throw new Error("OS credential entry failed canonical schema validation", {
      cause: parsed.error,
    });
  }
  return {
    activation,
    credential: { apiKey: parsed.data, secret },
  };
}

function errorSummary(
  error: unknown,
  credentialValue: readonly (string | null | undefined)[] = [],
): string {
  if (!(error instanceof Error)) {
    return "Error";
  }
  const name = error.name || "Error";
  const message = credentialSafeMessage(error, credentialValue).trim();
  return message && message !== name ? `${name}: ${message}` : name;
}
