import { redactCredentialText, type AventureProblemDetail } from "../../api/client";

export { redactCredentialText };

export function credentialSafeMessage(
  error: unknown,
  credentialValue: readonly (string | null | undefined)[] = [],
): string {
  const message = error instanceof Error ? error.message : String(error);
  return redactCredentialText(message, credentialValue);
}

/** Format RFC 9457 diagnostics without reflecting known credential material. */
export function credentialSafeProblemSummary(
  problem: AventureProblemDetail,
  credentialValue: readonly (string | null | undefined)[] = [],
): string {
  const title = redactCredentialText(problem.title, credentialValue);
  const detail = redactCredentialText(problem.detail?.trim() ?? "", credentialValue);
  return `${problem.status} ${title}${detail ? ` — ${detail}` : ""}`;
}
