import type { AventureAuthEnv } from "../../api/env";

/**
 * Canonicalize the API target used to partition local credentials. Plain HTTP
 * is intentionally limited to explicit loopback development.
 */
export interface CliApiTarget {
  readonly host: string;
  readonly origin: string;
  readonly isLoopback: boolean;
}

export function cliApiTarget(host: string): CliApiTarget {
  const candidate = host.trim();
  if (candidate.length === 0) throw new Error("API host must not be blank");
  const parsed = new URL(
    hasProtocol(candidate) ? candidate : `${defaultProtocol(candidate)}://${candidate}`,
  );
  const isLoopback = isLoopbackHostname(parsed.hostname);
  if (
    (parsed.protocol !== "https:" && parsed.protocol !== "http:") ||
    parsed.username.length > 0 ||
    parsed.password.length > 0 ||
    (parsed.pathname !== "/" && parsed.pathname !== "") ||
    parsed.search.length > 0 ||
    parsed.hash.length > 0
  ) {
    throw new Error("API host must contain only an HTTP(S) host and optional port");
  }
  if (parsed.protocol === "http:" && !isLoopback) {
    throw new Error("personal credentials require HTTPS except for loopback API hosts");
  }
  return { host: parsed.host.toLowerCase(), origin: parsed.origin, isLoopback };
}

export function normalizeCliApiEnvironment(environment: AventureAuthEnv): AventureAuthEnv {
  return { ...environment, host: cliApiTarget(environment.host).origin };
}

export function browserOriginForApiHost(host: string): string {
  const target = cliApiTarget(host);
  if (target.isLoopback) return "http://localhost:3000";
  if (target.host === "api.dev.aventure.vc") return "https://dev.aventure.vc";
  if (target.host === "api.staging.aventure.vc") return "https://staging.aventure.vc";
  if (target.host === "api.aventure.vc") return "https://aventure.vc";
  throw new Error(`no first-party browser origin is configured for API host ${target.host}`);
}

function hasProtocol(value: string): boolean {
  return /^[a-z][a-z\d+.-]*:\/\//iu.test(value);
}

function defaultProtocol(value: string): "http" | "https" {
  const authority = value.split("/", 1)[0]?.toLowerCase() ?? "";
  try {
    return isLoopbackHostname(new URL(`http://${authority}`).hostname) ? "http" : "https";
  } catch {
    return "https";
  }
}

export function isLoopbackHostname(hostname: string): boolean {
  const normalized = hostname.toLowerCase();
  return (
    normalized === "localhost" ||
    normalized === "127.0.0.1" ||
    normalized === "0.0.0.0" ||
    normalized === "[::1]"
  );
}
